def backoffice(request: Request) -> HTMLResponse:
    prefix = request.headers.get("x-forwarded-prefix", "").strip() if request else ""
    if not prefix.startswith("/") or prefix.startswith("//") or "\\" in prefix or any(char in prefix for char in "?#\"'<>\r\n"):
        prefix = ""
    redirect_path = f"{prefix.rstrip('/')}/backoffice" if prefix else "/news/backoffice"
    login_href = f"https://vaneworker.com/login?redirect={quote(redirect_path, safe='')}"
    body = (
        CONSOLE_STYLE
        + _console_header("管理后台", "W")
        + '<section id=auth class="panel console-card"><p id=authmsg data-i18n="console.gate">需要管理权限，请登录后使用。</p>'
          f'<a id=auth-login class=account-link href="{login_href}" data-i18n="console.login">登录 / 注册</a></section>'
        + "<div id=console hidden>"
        + CONSOLE_BODY
        + "</div>"
    )
    return _page("管理后台", body, CONSOLE_SCRIPT, ' data-mode="master"')


