def _console_header(title: str, logo: str) -> str:
    """The console header shared by master's backoffice and slaver's console.

    "抓取一次" now lives on the RSS card's title row; the header's right slot is
    the "投资信号" return link.
    """
    return (
        "<header class=console-header><div class=brand>"
        f'<div class=logo aria-hidden=true>{logo}</div><h1 data-i18n="console.title">{title}</h1></div>'
        '<div class=console-header-actions><div class=language-switch aria-label="Language" data-i18n-aria-label="console.language"><button type=button data-lang=zh onclick="setLanguage(\'zh\')">中文</button><button type=button data-lang=en onclick="setLanguage(\'en\')">EN</button></div>'
        '<a class=home-link href="./" data-i18n="console.portal">投资信号</a></div></header>'
    )


