def slaver_console(request: Request) -> HTMLResponse:
    from src.api.console import require_local_console

    require_local_console(request)
    body = CONSOLE_STYLE + _console_header("管理后台", "M") + "<div id=console>" + CONSOLE_BODY + "</div>"
    return _page("管理后台", body, CONSOLE_SCRIPT, ' data-mode="slaver"')
